using System.Net;
using System.Net.Sockets;
using System.Text;
namespace WirePulse;

public static class SelfTest
{
    static void Check(bool ok, string message) { if (!ok) throw new Exception(message); Console.WriteLine("PASS " + message); }
    public static int Run()
    {
        try
        {
            foreach (int rate in new[] { 44100, 48000, 96000, 192000 }) foreach (double hz in new[] { 0d, 31.25, 1000, 18000, rate / 2d }) { var spectrum = new Spectrum(); int samples = rate / 2; var data = new float[samples * 2]; for (int i = 0; i < samples; i++) { var v = (float)(.5 * Math.Cos(2 * Math.PI * hz * i / rate)); data[i * 2] = v; data[i * 2 + 1] = -v; } spectrum.Push(data, data.Length, 2, rate); var s = spectrum.Snapshot(); Check(Math.Abs(s.PeakHz - hz) <= rate / (double)s.FftSize, $"FFT {rate} Hz / {hz} Hz stereo antiphase"); Check(s.Bands.Max() > .1, "signal remains visible"); Check(s.Low[0] == 0 && s.High[^1] == rate / 2d, "DC–Nyquist coverage"); for (int b = 1; b < 64; b++) if (Math.Abs(s.Low[b] - s.High[b - 1]) > .001) throw new Exception("Band gap"); }
            var silent = new Spectrum(); silent.Push(new float[24000], 24000, 1, 48000); Check(silent.Snapshot().Bands.All(x => x == 0), "silence has zero energy"); Check(MediaService.Provider("org.mpris.MediaPlayer2.cider") == "Cider", "native Cider provider"); Check(MediaService.Provider("chrome", "https://music.youtube.com/watch?v=test") == "YouTube Music", "browser provider"); CiderTest().GetAwaiter().GetResult(); CiderV2Test().GetAwaiter().GetResult(); ProfileTest(); SettingsTest(); StartupTest(); GraphicsTest(); ParticleTempoTest(); SceneTest(); InstanceTest(); RenderTest(); return 0;
        }
        catch (Exception e) { Console.Error.WriteLine(e); return 1; }
    }
    static void GraphicsTest(){Check(GraphicsBackend.FallbackOrder("Vulkan").SequenceEqual(new[]{"Vulkan","DirectX 11","CPU (compatibilidad)"}),"Vulkan falls back to DirectX 11 and CPU");Check(GraphicsBackend.FallbackOrder("CPU (compatibilidad)").SequenceEqual(new[]{"CPU (compatibilidad)"}),"CPU request never silently enables GPU");Check(GraphicsBackend.Normalize("DirectX 12")=="Automático"&&!GraphicsBackend.Choices.Contains("DirectX 12"),"unsupported backend is never advertised as active");Check(GraphicsBackend.DetectPlatform("Avalonia.OpenGL.Egl.EglContext")=="DirectX 11"&&GraphicsBackend.DetectPlatform("Avalonia.Win32.OpenGl.WglContext")=="OpenGL"&&GraphicsBackend.DetectPlatform("Avalonia.Vulkan.VulkanContext")=="Vulkan"&&GraphicsBackend.DetectPlatform(null)=="CPU (compatibilidad)","actual context diagnostics distinguish Windows graphics APIs");}
    static void ParticleTempoTest(){
     var stars=new StarMotion();var a=stars.Position(0,1920,1080);var b=stars.Position(1,1920,1080);for(int i=0;i<60;i++)stars.Advance(120,1/60d,20,135,false);var aa=stars.Position(0,1920,1080);var bb=stars.Position(1,1920,1080);Check(Math.Abs((aa.X-a.X)-(bb.X-b.X))>1,"stars have independent trajectories and speed");stars.Advance(120,.1,200,0,true);Check(stars.Position(0,1920,1080)==aa,"paused particles remain stationary");
     foreach(var json in new[]{"{\"bpm\":128.5}","{\"attributes\":{\"tempo\":\"128.5\"}}","{\"audioFeatures\":{\"tempo\":128.5}}"})Check(PlaybackTempo.Read(System.Text.Json.Nodes.JsonNode.Parse(json))==128.5,"optional Cider tempo metadata");
     foreach(var json in new[]{"{}","{\"bpm\":true}","{\"bpm\":-1}","{\"bpm\":9999}","{\"tempo\":\"unknown\"}"})Check(PlaybackTempo.Read(System.Text.Json.Nodes.JsonNode.Parse(json))==0,"missing or invalid tempo falls back to audio");
     var track=new Track("Cider",Title:"Fixture",Playing:true){Bpm=128.5};Check(PlaybackTempo.Resolve(track,90)==128.5,"active Cider BPM takes priority");Check(PlaybackTempo.Resolve(track with{Playing=false},90)==90&&PlaybackTempo.Resolve(track with{Bpm=0},90)==90&&PlaybackTempo.Resolve(track with{Provider="Spotify"},90)==90&&PlaybackTempo.Resolve(track with{Updated=DateTimeOffset.UtcNow.AddSeconds(-8)},90)==90,"paused, missing, unrelated and stale metadata do not override audio");
    }
    static void SceneTest(){foreach(double expected in new[]{40d,60,90,120,165,190,220,240}){var detector=new BeatTracker();var bands=new double[64];var ranges=Enumerable.Repeat(200d,64).ToArray();BeatFrame result=default;double period=60/expected;for(int i=0;i<900;i++){double phase=i/60d%period,energy=phase<.09?Math.Exp(-phase*30)*.7:0;Array.Fill(bands,energy);result=detector.Feed(bands,ranges,energy,1/60d);}Check(Math.Abs(result.Bpm-expected)<8,$"audio onset tempo {expected} BPM estimated as {result.Bpm:F1}");for(int i=0;i<180;i++)result=detector.Feed(new double[64],ranges,0,1/60d);Check(result.Bpm==0&&result.Pulse==0,"silence removes beat acceleration");}
     foreach(double expected in new[]{90d,120,165}){var spectrum=new Spectrum();int rate=48000;var pcm=new float[rate*12];for(int i=0;i<pcm.Length;i++){double t=i/(double)rate,phase=t%(60/expected);pcm[i]=(float)(.7*Math.Exp(-phase*45)*Math.Sin(2*Math.PI*65*t));}spectrum.Push(pcm,pcm.Length,1,rate);Check(Math.Abs(spectrum.Snapshot().Bpm-expected)<8,$"PCM kick audio estimates {expected} BPM: {spectrum.Snapshot().Bpm:F1}");}
     var baseMotion=new BackgroundMotion();for(int i=0;i<60;i++)baseMotion.Advance(1/60d,20,135,3,0,0,false);Check(Math.Abs(baseMotion.X+Math.Sqrt(200))<1e-6&&Math.Abs(baseMotion.Y-Math.Sqrt(200))<1e-6,"silent background drifts upper right to lower left at constant speed");var beatMotion=new BackgroundMotion();for(int i=0;i<60;i++)beatMotion.Advance(1/60d,20,135,3,1,120,false);Check(Math.Abs(beatMotion.X)>Math.Abs(baseMotion.X)*3.9,"beats accelerate displacement without teleporting");double before=beatMotion.X;beatMotion.Advance(.1,20,0,3,1,120,true);Check(beatMotion.X==before,"pause freezes background movement");Check(SpaceBackground.Wrap(-1,100)==99&&SpaceBackground.Wrap(201,100)==1,"infinite background wraps continuously");Check(ClockText.Format(new DateTime(2026,1,1,0,5,0),true,System.Globalization.CultureInfo.InvariantCulture)=="00:05"&&ClockText.Format(new DateTime(2026,1,1,13,5,0),false,System.Globalization.CultureInfo.InvariantCulture)=="01:05 PM","clock supports explicit 24h and 12h formats");
    }
    static void StartupTest()
    {
        Check(StartupRegistration.ShouldPrompt(false, false, false) && !StartupRegistration.ShouldPrompt(true, false, false) && !StartupRegistration.ShouldPrompt(false, true, false) && !StartupRegistration.ShouldPrompt(false, false, true), "startup consent appears once and never during autostart or headless probes"); string folder = Path.Combine(Path.GetTempPath(), "wirepulse-startup-" + Guid.NewGuid()); try { var registration = new StartupRegistration("/opt/Folder with spaces/WirePulse % $ ` \\".Replace("\\", "\\"), folder, windows: false); Check(!registration.Enabled, "startup is disabled by default"); registration.SetEnabled(true); Check(registration.Enabled, "Linux per-user startup enables"); var entry = File.ReadAllText(Path.Combine(folder, "wirepulse.desktop")); Check(entry.Contains(" --autostart --no-settings") && entry.Contains("%%") && entry.Contains("TryExec="), "Linux startup quotes paths and stays quiet"); registration.SetEnabled(false); Check(!registration.Enabled, "Linux per-user startup disables"); } finally { if (Directory.Exists(folder)) Directory.Delete(folder, true); }
        if (OperatingSystem.IsWindows()) { string key = @"Software\WirePulseTests\" + Guid.NewGuid(); try { var registration = new StartupRegistration(@"C:\Folder with spaces\WirePulse.exe", registryPath: key, windows: true); Check(!registration.Enabled, "Windows startup starts disabled"); registration.SetEnabled(true); using (var registry = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(key)) { Check(registry?.GetValue("WirePulse") as string == "\"C:\\Folder with spaces\\WirePulse.exe\" --autostart --no-settings", "Windows startup command quotes its executable"); } Check(registration.Enabled, "Windows per-user startup enables"); registration.SetPriority(true); Check(registration.Enabled && registration.PriorityEnabled, "Windows priority login task enables"); new StartupRegistration(@"C:\Other\WirePulse.exe",registryPath:key,windows:true).RemoveOwned(); Check(registration.PriorityEnabled,"Uninstall of another executable preserves priority task"); using(var run = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(key)) Check(run?.GetValue("WirePulse") == null, "Priority login removes duplicate Run entry"); registration.SetPriority(false); Check(registration.Enabled && !registration.PriorityEnabled, "Priority login switches back to normal startup"); registration.SetPriority(true); registration.SetEnabled(false); Check(!registration.PriorityEnabled, "Disable startup removes priority task"); Check(!registration.Enabled, "Windows per-user startup disables"); } finally { new StartupRegistration(registryPath:key, windows:true).SetEnabled(false); Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(key, false); } }
    }
    static void InstanceTest() { string name = "-test-" + Guid.NewGuid(); System.Diagnostics.Process Start(int hold) { var p = new System.Diagnostics.Process { StartInfo = new() { FileName = Environment.ProcessPath!, RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false } }; foreach (var a in new[] { "--instance-lock-probe", hold.ToString(), "--probe-name", name }) p.StartInfo.ArgumentList.Add(a); p.Start(); return p; } using var first = Start(3000); Check(first.StandardOutput.ReadLine() == "ACQUIRED", "first instance acquires render/audio ownership"); using var second = Start(1); if (!second.WaitForExit(5000)) { second.Kill(true); throw new Exception("Second launch hung"); } Check(second.ExitCode == 2, "second process cannot duplicate renderer/audio capture"); first.Kill(true); first.WaitForExit(); using var third = Start(1); third.WaitForExit(); Check(third.ExitCode == 0, "single-instance lock recovers after a crashed process"); }
    static void SettingsTest() { string id = "malformed-" + Guid.NewGuid(), hash = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(id)))[..16], path = Path.Combine(Settings.Folder, "display-" + hash + ".json"); Directory.CreateDirectory(Settings.Folder); try { File.WriteAllText(path, "{\"values\":{\"wirecolor\":\"invalid-colour\",\"fps\":9999,\"smoothing\":2,\"sphere\":\"invalid-bool\"},\"topMargin\":1e90,\"renderProfile\":\"unknown\"}"); var s = new Settings(id); Check(s.N("fps") == 360 && s.N("smoothing") == .98 && s.TopMargin == 80, "loaded settings constrain invalid ranges"); Check(s.On("sphere") && s.RenderProfile == "Automático", "malformed settings restore usable defaults"); _ = VisualizerOptions.Read(s); Check(true, "invalid colours cannot crash renderer"); } finally { File.Delete(path); } }
    static void RenderTest()
    {
        {var a=new System.Numerics.Vector3(0,0,-1);var b=new System.Numerics.Vector3(2,0,1);Check(OrbMesh.ClipFront(ref a,ref b)&&a.Z==0&&a.X==1,"rear orb lines clip at the silhouette");a=new(0,0,-2);b=new(0,0,-1);Check(!OrbMesh.ClipFront(ref a,ref b),"rear orb edges are invisible");}
        foreach(double hz in new[]{75d,165}){var budget=new FrameBudget();var times=new List<double>();for(int i=0;i<10000;i++){double t=i/1000d;if(budget.Due(t,hz))times.Add(t);}Check(times.Count<=(int)(10*hz),$"GPU submission ceiling {hz} Hz");Check(times.All(t=>times.Count(x=>x>t-1+1e-9&&x<=t)<=(int)hz),$"rolling GPU budget {hz} Hz");}
        foreach (double clock in new[] { 59.94, 60, 64, 75, 120, 144, 165, 240 }) foreach (double target in new[] { 30d, 60, 75, 120, 165, 240 }) { var pacer = new FramePacer(); int count = 0; for (int i = 0; i < (int)(clock * 10); i++) if (pacer.Due(i / clock, target)) count++; double expected = Math.Min(clock, target) * 10; Check(Math.Abs(count - expected) <= 2, $"frame cadence {target} FPS on {clock} Hz clock: {count / 10d:F1}"); }
        foreach (int density in new[] { 12, 24, 42, 72 })
        {
            var mesh = new OrbMesh(density); Check(mesh.Vertices.Count(p => p.Y == 1) == 1 && mesh.Vertices.Count(p => p.Y == -1) == 1, "single connected vertex per pole"); foreach (var (a, b) in mesh.Edges) { var p = mesh.Vertices[a]; var q = mesh.Vertices[b]; if (Math.Abs(p.X - q.X) + Math.Abs(p.Y - q.Y) + Math.Abs(p.Z - q.Z) < 1e-10) throw new Exception("Zero length polar edge"); }
            var quiet = new System.Numerics.Vector3[mesh.Vertices.Length]; var loud = new System.Numerics.Vector3[quiet.Length]; mesh.Project(quiet, new double[64], .4, 1.2, 100, 200, 200, 2, true); mesh.Project(loud, Enumerable.Repeat(1d, 64).ToArray(), .4, 1.2, 100, 200, 200, 2, true); Check(System.Numerics.Vector3.Distance(quiet[0], loud[0]) < 1e-6 && System.Numerics.Vector3.Distance(quiet[^1], loud[^1]) < 1e-6, "audio cannot create polar needles"); Check(quiet.Zip(loud, (a, b) => System.Numerics.Vector3.Distance(a, b)).Max() > 1, "orb body still deforms with audio");
        }
    }
    static void ProfileTest() { var root = new Settings(); root.Values["sphereX"] = System.Text.Json.Nodes.JsonValue.Create(77d); var id = "test-" + Guid.NewGuid(); var a = new Settings(id, root); Check(a.N("sphereX") == 77, "new display copies shared layout"); a.Values["sphereX"] = System.Text.Json.Nodes.JsonValue.Create(22d); Check(root.N("sphereX") == 77, "independent display preserves shared layout"); a.Save(); var b = new Settings(id, root); Check(b.N("sphereX") == 22, "display profile persists independently"); var key = "display-" + Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(id)))[..16] + ".json"; File.Delete(Path.Combine(Settings.Folder, key)); }
    static async Task CiderV2Test() { var listener = new TcpListener(IPAddress.Loopback, 0); listener.Start(); int port = ((IPEndPoint)listener.LocalEndpoint).Port; var server = Task.Run(async () => { using var socket = await listener.AcceptTcpClientAsync(); using var stream = socket.GetStream(); using var reader = new StreamReader(stream, Encoding.ASCII, false, 1024, true); var line = await reader.ReadLineAsync(); Check(line!.StartsWith("GET /api/v2/playback "), "Cider v2 snapshot endpoint"); string? h; while (!string.IsNullOrEmpty(h = await reader.ReadLineAsync())) { } var body = "{\"data\":{\"state\":\"paused\",\"nowPlaying\":{\"name\":\"Fixture v2\",\"artistName\":\"WirePulse\",\"bpm\":128.5,\"durationInMillis\":240000},\"time\":{\"currentTime\":45.2,\"duration\":240}}}"; var response = Encoding.UTF8.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " + Encoding.UTF8.GetByteCount(body) + "\r\nConnection: close\r\n\r\n" + body); await stream.WriteAsync(response); }); var media = new MediaService(new Settings { MediaSource = "Cider", CiderUrl = $"http://127.0.0.1:{port}" }); await media.Poll(); await server.WaitAsync(TimeSpan.FromSeconds(10)); listener.Stop(); Check(media.Current.Title == "Fixture v2" && !media.Current.Playing && media.Current.Position == 45.2 && media.Current.Bpm==128.5, "Cider v2 paused metadata and position"); }
    static async Task CiderTest()
    {
        var listener = new TcpListener(IPAddress.Loopback, 0); listener.Start(); int port = ((IPEndPoint)listener.LocalEndpoint).Port; var server = Task.Run(async () => { for (int n = 0; n < 3; n++) { using var socket = await listener.AcceptTcpClientAsync(); using var stream = socket.GetStream(); using var reader = new StreamReader(stream, Encoding.ASCII, false, 1024, true); var line = await reader.ReadLineAsync(); bool token = false; string? header; while (!string.IsNullOrEmpty(header = await reader.ReadLineAsync())) if (header.Equals("apptoken: fixture-token", StringComparison.OrdinalIgnoreCase)) token = true; Check(token, "Cider auth header"); if (line!.Contains("/api/v2/")) { await stream.WriteAsync(Encoding.ASCII.GetBytes("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")); continue; } var body = line!.Contains("is-playing") ? "{\"is_playing\":true}" : "{\"info\":{\"name\":\"Fixture\",\"artistName\":\"WirePulse\",\"albumName\":\"Test\",\"tempo\":\"128.5\",\"durationInMillis\":60000,\"currentPlaybackTime\":12,\"artwork\":{\"url\":\"https://example.invalid/{w}x{h}.jpg\"}}}"; var response = Encoding.UTF8.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " + Encoding.UTF8.GetByteCount(body) + "\r\nConnection: close\r\n\r\n" + body); await stream.WriteAsync(response); } });
        var settings = new Settings { MediaSource = "Cider", CiderUrl = $"http://127.0.0.1:{port}", CiderToken = "fixture-token" }; var media = new MediaService(settings); await media.Poll(); await server.WaitAsync(TimeSpan.FromSeconds(10)); listener.Stop(); Check(media.Current.Provider == "Cider" && media.Current.Title == "Fixture" && media.Current.Playing && media.Current.Position == 12 && media.Current.Duration == 60 && media.Current.Bpm==128.5, "Cider API metadata/state/time"); Check(media.Current.Artwork == "https://example.invalid/600x600.jpg", "Cider artwork template");
    }
}
